import { BadRequestException, ForbiddenException } from '@nestjs/common';
import type { IdBusinessV2RechargeJob } from '@prisma/client';
import { timingSafeEqual } from 'node:crypto';
import { hash, object, safeDocument } from './recharge-validation';

const privateKey = '_callback_private_v1';
const acknowledgement = { ok: true };

// Canonical receipt material excludes only the timestamp generated by safeDocument.
export function rechargeDocumentDigest(value: unknown): string {
  const canonical = (item: unknown, parent?: string): unknown => {
    if (Array.isArray(item)) return item.map((value) => canonical(value));
    if (!item || typeof item !== 'object') return item;
    return Object.fromEntries(
      Object.entries(item)
        .filter(
          ([key, value]) => value !== undefined && !(parent === 'network' && key === 'observedAt')
        )
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([key, value]) => [key, canonical(value, key)])
    );
  };
  return hash(JSON.stringify(canonical(value)) ?? 'undefined');
}

export function assertNoPrivateRechargeCallback(value: unknown) {
  if (!value || typeof value !== 'object') return;
  for (const [key, item] of Object.entries(value)) {
    if (key.startsWith('_')) throw new BadRequestException('执行回执包含不可写入的内部字段');
    assertNoPrivateRechargeCallback(item);
  }
}

function receiptIdentity(jobId: string, nonceHash: string) {
  return hash(`recharge-receipt-v1:${jobId}:${nonceHash}`);
}

export function authorizeLocalRechargeCallback(
  job: IdBusinessV2RechargeJob | null,
  token: unknown
) {
  if (!job || job.action !== 'bitbrowser' || typeof token !== 'string')
    throw new ForbiddenException('本机连接凭据无效');
  const stored = object(object(job.result ?? {})[privateKey] ?? {});
  const actual = job.nonceHash ? hash(token) : receiptIdentity(job.id, hash(token));
  const expected = job.nonceHash ?? stored.identityHash;
  if (
    typeof expected !== 'string' ||
    actual.length !== expected.length ||
    !timingSafeEqual(Buffer.from(actual), Buffer.from(expected))
  )
    throw new ForbiddenException('本机连接凭据无效');
  return job;
}

export function rechargeCallbackDigest(callback: Record<string, unknown>) {
  return rechargeDocumentDigest({
    type: callback.type,
    accountKey: callback.accountKey,
    fileKey: callback.fileKey,
    revision: callback.revision,
    ...(callback.result !== undefined ? { result: safeDocument(callback.result) } : {}),
    ...(callback.document !== undefined ? { document: safeDocument(callback.document) } : {})
  });
}

export function replayRechargeReceipt(
  job: IdBusinessV2RechargeJob,
  callback: Record<string, unknown>
) {
  const stored = object(object(job.result ?? {})[privateKey] ?? {});
  const digest = rechargeCallbackDigest(callback);
  if (callback.type === 'finished' && stored.firstTerminalDigest === digest)
    return stored.firstTerminalResponse ?? acknowledgement;
  if (stored.latestFactDigest === digest) return stored.latestFactResponse ?? acknowledgement;
  return undefined;
}

export function withRechargeReceipt(
  job: IdBusinessV2RechargeJob,
  result: Record<string, unknown>,
  callback: Record<string, unknown>,
  response: unknown,
  factsOnly = false
) {
  if (job.action !== 'bitbrowser') return result;
  const stored = object(object(job.result ?? {})[privateKey] ?? {});
  const identityHash =
    stored.identityHash ?? (job.nonceHash ? receiptIdentity(job.id, job.nonceHash) : undefined);
  if (!identityHash) return result;
  const digest = rechargeCallbackDigest(callback);
  return {
    ...result,
    [privateKey]: {
      ...stored,
      identityHash,
      ...(callback.type === 'finished' && !stored.firstTerminalDigest
        ? { firstTerminalDigest: digest, firstTerminalResponse: response }
        : {}),
      ...(factsOnly ? { latestFactDigest: digest, latestFactResponse: response } : {})
    }
  };
}

export function isRetiredRechargeCallback(job: IdBusinessV2RechargeJob) {
  return (
    job.state === 'finished' ||
    job.leaseUntil.getTime() < Date.now() ||
    ['cancelling', 'cancelled'].includes(String(object(job.result ?? {}).status))
  );
}
